const cardsMetodos = [
  { lang: "JavaScript", question: ".slice()  ·  JavaScript · Texto", answer: "Extrae una parte del string entre dos posiciones. Ej: const fruta = \"manzana\"; const trozo = fruta.slice(0, 3); console.log(trozo); // → \"man\"" },
  { lang: "JavaScript", question: ".split()  ·  JavaScript · Texto", answer: "Divide un string en un array de trozos según un separador. Ej: const csv = \"rojo,verde,azul\"; const colores = csv.split(\",\"); console.log(colores); // → [\"rojo\", \"verde\", \"azul\"]" },
  { lang: "JavaScript", question: ".replace()  ·  JavaScript · Texto", answer: "Sustituye la primera coincidencia de un texto por otro. Ej: const frase = \"hola mundo\"; const nueva = frase.replace(\"mundo\", \"JS\"); console.log(nueva); // → \"hola JS\"" },
  { lang: "JavaScript", question: ".trim()  ·  JavaScript · Texto", answer: "Elimina los espacios en blanco del principio y el final. Ej: const entrada = \"   hola   \"; const limpio = entrada.trim(); console.log(limpio); // → \"hola\"" },
  { lang: "JavaScript", question: ".toUpperCase()  ·  JavaScript · Texto", answer: "Convierte todas las letras del string a mayúsculas. Ej: const nombre = \"ana\"; console.log(nombre.toUpperCase()); // → \"ANA\"" },
  { lang: "JavaScript", question: ".includes()  ·  JavaScript · Texto", answer: "Comprueba si un string contiene un fragmento de texto. Ej: const fruta = \"manzana\"; if (fruta.includes(\"man\")) {   console.log(\"Contiene 'man'\"); }" },
  { lang: "JavaScript", question: ".padStart()  ·  JavaScript · Texto", answer: "Rellena el string por la izquierda hasta alcanzar una longitud. Ej: const hora = \"5\"; const horaFormateada = hora.padStart(2, \"0\"); console.log(horaFormateada); // → \"05\"" },
  { lang: "Python", question: ".strip()  ·  Python · Texto", answer: "Elimina los espacios en blanco del principio y el final. Ej: entrada = \"   hola   \" limpio = entrada.strip() print(limpio)  # → \"hola\"" },
  { lang: "Python", question: ".split()  ·  Python · Texto", answer: "Divide un string en una lista de trozos según un separador. Ej: csv = \"rojo,verde,azul\" colores = csv.split(\",\") print(colores)  # → ['rojo', 'verde', 'azul']" },
  { lang: "Python", question: ".replace()  ·  Python · Texto", answer: "Sustituye todas las coincidencias de un texto por otro. Ej: frase = \"hola mundo\" nueva = frase.replace(\"mundo\", \"Py\") print(nueva)  # → \"hola Py\"" },
  { lang: "Python", question: ".upper()  ·  Python · Texto", answer: "Convierte todas las letras del string a mayúsculas. Ej: nombre = \"ana\" print(nombre.upper())  # → \"ANA\"" },
  { lang: "Python", question: ".lower()  ·  Python · Texto", answer: "Convierte todas las letras del string a minúsculas. Ej: nombre = \"ANA\" print(nombre.lower())  # → \"ana\"" },
  { lang: "Python", question: ".find()  ·  Python · Texto", answer: "Devuelve la posición de la primera coincidencia, o -1. Ej: fruta = \"manzana\" posicion = fruta.find(\"man\") print(posicion)  # → 0" },
  { lang: "Python", question: ".format()  ·  Python · Texto", answer: "Inserta valores dentro de un string usando marcadores {}. Ej: plantilla = \"Hola {}\" mensaje = plantilla.format(\"Ana\") print(mensaje)  # → \"Hola Ana\"" },
  { lang: "JavaScript", question: ".map()  ·  JavaScript · Arrays y objetos", answer: "Crea un nuevo array transformando cada elemento con una función. Ej: const numeros = [1, 2, 3]; const dobles = numeros.map(n => n * 2); console.log(dobles); // → [2, 4, 6]" },
  { lang: "JavaScript", question: ".filter()  ·  JavaScript · Arrays y objetos", answer: "Crea un nuevo array solo con los elementos que cumplen una condición. Ej: const numeros = [1, 2, 3, 4]; const pares = numeros.filter(n => n % 2 === 0); console.log(pares); // → [2, 4]" },
  { lang: "JavaScript", question: ".reduce()  ·  JavaScript · Arrays y objetos", answer: "Combina todos los elementos del array en un único valor acumulado. Ej: const numeros = [1, 2, 3]; const suma = numeros.reduce((acc, n) => acc + n, 0); console.log(suma); // → 6" },
  { lang: "JavaScript", question: ".push()  ·  JavaScript · Arrays y objetos", answer: "Añade uno o más elementos al final del array. Ej: const frutas = [\"manzana\", \"pera\"]; frutas.push(\"uva\"); console.log(frutas); // → [\"manzana\", \"pera\", \"uva\"]" },
  { lang: "JavaScript", question: ".pop()  ·  JavaScript · Arrays y objetos", answer: "Elimina y devuelve el último elemento del array. Ej: const frutas = [\"manzana\", \"pera\", \"uva\"]; const ultima = frutas.pop(); console.log(ultima, frutas); // → \"uva\" [\"manzana\", \"pera\"]" },
  { lang: "JavaScript", question: ".sort()  ·  JavaScript · Arrays y objetos", answer: "Ordena los elementos del array modificando el original. Ej: const numeros = [3, 1, 2]; numeros.sort(); console.log(numeros); // → [1, 2, 3]" },
  { lang: "JavaScript", question: ".concat()  ·  JavaScript · Arrays y objetos", answer: "Une dos o más arrays en uno nuevo. Ej: const a = [1, 2]; const b = [3, 4]; const unido = a.concat(b); console.log(unido); // → [1, 2, 3, 4]" },
  { lang: "Python", question: ".append()  ·  Python · Arrays y objetos", answer: "Añade un elemento al final de la lista. Ej: frutas = [\"manzana\", \"pera\"] frutas.append(\"uva\") print(frutas)  # → ['manzana', 'pera', 'uva']" },
  { lang: "Python", question: ".pop()  ·  Python · Arrays y objetos", answer: "Elimina y devuelve el último elemento de la lista. Ej: frutas = [\"manzana\", \"pera\", \"uva\"] ultima = frutas.pop() print(ultima, frutas)  # → uva ['manzana', 'pera']" },
  { lang: "Python", question: ".sort()  ·  Python · Arrays y objetos", answer: "Ordena los elementos de la lista modificando la original. Ej: numeros = [3, 1, 2] numeros.sort() print(numeros)  # → [1, 2, 3]" },
  { lang: "Python", question: ".reverse()  ·  Python · Arrays y objetos", answer: "Invierte el orden de los elementos de la lista. Ej: numeros = [1, 2, 3] numeros.reverse() print(numeros)  # → [3, 2, 1]" },
  { lang: "Python", question: ".index()  ·  Python · Arrays y objetos", answer: "Devuelve la posición de la primera coincidencia de un valor. Ej: numeros = [10, 20, 30] posicion = numeros.index(20) print(posicion)  # → 1" },
  { lang: "Python", question: ".count()  ·  Python · Arrays y objetos", answer: "Cuenta cuántas veces aparece un valor en la lista. Ej: numeros = [1, 2, 2, 3] veces = numeros.count(2) print(veces)  # → 2" },
  { lang: "Python", question: ".extend()  ·  Python · Arrays y objetos", answer: "Añade todos los elementos de otra lista al final. Ej: a = [1, 2] b = [3, 4] a.extend(b) print(a)  # → [1, 2, 3, 4]" },
  { lang: "JavaScript", question: "Number()  ·  JavaScript · Conversión", answer: "Convierte un valor a tipo número. Ej: const texto = \"42\"; const numero = Number(texto); console.log(numero + 8); // → 50" },
  { lang: "JavaScript", question: "String()  ·  JavaScript · Conversión", answer: "Convierte un valor a tipo texto. Ej: const edad = 42; const texto = String(edad); console.log(\"Tengo \" + texto + \" años\");" },
  { lang: "JavaScript", question: "parseInt()  ·  JavaScript · Conversión", answer: "Convierte un texto a número entero, ignorando decimales. Ej: const medida = \"42px\"; const numero = parseInt(medida); console.log(numero); // → 42" },
  { lang: "JavaScript", question: "JSON.stringify()  ·  JavaScript · Conversión", answer: "Convierte un objeto o array en un texto JSON. Ej: const persona = { nombre: \"Ana\", edad: 30 }; const texto = JSON.stringify(persona); console.log(texto); // → '{\"nombre\":\"Ana\",\"edad\":30}'" },
  { lang: "JavaScript", question: "Boolean()  ·  JavaScript · Conversión", answer: "Convierte un valor a true o false. Ej: const valores = [0, 1, \"\", \"hola\"]; console.log(valores.map(v => Boolean(v))); // → [false, true, false, true]" },
  { lang: "Python", question: "int()  ·  Python · Conversión", answer: "Convierte un valor a tipo entero. Ej: texto = \"42\" numero = int(texto) print(numero + 8)  # → 50" },
  { lang: "Python", question: "str()  ·  Python · Conversión", answer: "Convierte un valor a tipo texto. Ej: edad = 42 texto = str(edad) print(\"Tengo \" + texto + \" años\")" },
  { lang: "Python", question: "float()  ·  Python · Conversión", answer: "Convierte un valor a número decimal. Ej: texto = \"3.14\" numero = float(texto) print(numero * 2)  # → 6.28" },
  { lang: "Python", question: "json.dumps()  ·  Python · Conversión", answer: "Convierte un diccionario o lista en un texto JSON. Ej: import json  persona = {\"nombre\": \"Ana\", \"edad\": 30} texto = json.dumps(persona) print(texto)  # → '{\"nombre\": \"Ana\", \"edad\": 30}'" },
  { lang: "Python", question: "bool()  ·  Python · Conversión", answer: "Convierte un valor a True o False. Ej: valores = [0, 1, \"\", \"hola\"] print([bool(v) for v in valores]) # → [False, True, False, True]" },
  { lang: "JavaScript", question: "document.querySelector()  ·  JavaScript · DOM", answer: "Devuelve el primer elemento que coincide con un selector CSS. Ej: const boton = document.querySelector(\".btn\"); boton.style.color = \"red\";" },
  { lang: "JavaScript", question: "document.getElementById()  ·  JavaScript · DOM", answer: "Devuelve el elemento cuyo id coincide exactamente. Ej: const titulo = document.getElementById(\"titulo\"); titulo.textContent = \"Nuevo título\";" },
  { lang: "JavaScript", question: ".addEventListener()  ·  JavaScript · DOM", answer: "Registra una función que se ejecuta cuando ocurre un evento. Ej: const boton = document.getElementById(\"saludar\"); boton.addEventListener(\"click\", () => {   alert(\"¡Hola!\"); });" },
  { lang: "JavaScript", question: ".createElement()  ·  JavaScript · DOM", answer: "Crea un nuevo nodo HTML que aún no está en la página. Ej: const li = document.createElement(\"li\"); li.textContent = \"Nueva tarea\"; // todavía no está en la página" },
  { lang: "JavaScript", question: ".appendChild()  ·  JavaScript · DOM", answer: "Inserta un nodo como último hijo de un elemento. Ej: const lista = document.getElementById(\"lista\"); const li = document.createElement(\"li\"); li.textContent = \"Nueva tarea\"; lista.appendChild(li); // ahora sí se ve en pantalla" },
  { lang: "JavaScript", question: ".classList.add()  ·  JavaScript · DOM", answer: "Añade una o más clases CSS a un elemento. Ej: const tarjeta = document.querySelector(\".tarjeta\"); tarjeta.classList.add(\"activa\");" },
  { lang: "JavaScript", question: ".setAttribute()  ·  JavaScript · DOM", answer: "Establece el valor de un atributo HTML en un elemento. Ej: const imagen = document.querySelector(\"img\"); imagen.setAttribute(\"alt\", \"Foto de perfil\");" },
  { lang: "JavaScript", question: ".textContent  ·  JavaScript · DOM", answer: "Obtiene o establece el texto plano de un elemento, sin HTML. Ej: const parrafo = document.querySelector(\"p\"); parrafo.textContent = \"Hola\"; // muestra el texto \"Hola\" sin interpretar HTML" },
  { lang: "JavaScript", question: "Math.round()  ·  JavaScript · Matemáticas", answer: "Redondea un número al entero más cercano. Ej: const precio = 19.6; console.log(Math.round(precio)); // → 20" },
  { lang: "JavaScript", question: "Math.random()  ·  JavaScript · Matemáticas", answer: "Genera un decimal aleatorio entre 0 (incluido) y 1 (excluido). Ej: const aleatorio = Math.random(); console.log(aleatorio); // → un decimal entre 0 y 1, ej: 0.3721" },
  { lang: "JavaScript", question: "Math.max()  ·  JavaScript · Matemáticas", answer: "Devuelve el valor más alto de una lista de números. Ej: const puntuaciones = [3, 7, 2]; console.log(Math.max(...puntuaciones)); // → 7" },
  { lang: "JavaScript", question: "Math.floor()  ·  JavaScript · Matemáticas", answer: "Redondea un número hacia abajo, al entero inferior. Ej: const precio = 4.9; console.log(Math.floor(precio)); // → 4" },
  { lang: "JavaScript", question: "Math.abs()  ·  JavaScript · Matemáticas", answer: "Devuelve el valor absoluto (sin signo) de un número. Ej: const diferencia = 5 - 12; console.log(Math.abs(diferencia)); // → 7" },
  { lang: "Python", question: "round()  ·  Python · Matemáticas", answer: "Redondea un número al entero más cercano. Ej: precio = 19.6 print(round(precio))  # → 20" },
  { lang: "Python", question: "random.random()  ·  Python · Matemáticas", answer: "Genera un decimal aleatorio entre 0.0 y 1.0. Ej: import random  aleatorio = random.random() print(aleatorio)  # → un decimal entre 0.0 y 1.0" },
  { lang: "Python", question: "max()  ·  Python · Matemáticas", answer: "Devuelve el valor más alto de una secuencia de números. Ej: puntuaciones = [3, 7, 2] print(max(puntuaciones))  # → 7" },
  { lang: "Python", question: "math.floor()  ·  Python · Matemáticas", answer: "Redondea un número hacia abajo, al entero inferior. Ej: import math  precio = 4.9 print(math.floor(precio))  # → 4" },
  { lang: "Python", question: "abs()  ·  Python · Matemáticas", answer: "Devuelve el valor absoluto (sin signo) de un número. Ej: diferencia = 5 - 12 print(abs(diferencia))  # → 7" },
  { lang: "JavaScript", question: ".then()  ·  JavaScript · Promesas", answer: "Registra una función que se ejecuta cuando la promesa se resuelve con éxito. Ej: fetch(\"/api/usuarios\")   .then(respuesta => respuesta.json())   .then(datos => console.log(datos));" },
  { lang: "JavaScript", question: ".catch()  ·  JavaScript · Promesas", answer: "Registra una función que se ejecuta cuando la promesa es rechazada (hay un error). Ej: fetch(\"/api/usuarios\")   .then(respuesta => respuesta.json())   .catch(error => console.error(\"Algo falló:\", error));" },
  { lang: "JavaScript", question: ".finally()  ·  JavaScript · Promesas", answer: "Registra una función que se ejecuta siempre, tanto si la promesa se resuelve como si falla. Ej: mostrarCargando(); fetch(\"/api/usuarios\")   .then(res => res.json())   .finally(() => ocultarCargando());" },
  { lang: "JavaScript", question: "Promise.all()  ·  JavaScript · Promesas", answer: "Espera a que todas las promesas del array se resuelvan, o falla en cuanto una falla. Ej: const p1 = fetch(\"/api/usuarios\"); const p2 = fetch(\"/api/productos\"); Promise.all([p1, p2]).then(([r1, r2]) => {   console.log(\"Ambas peticiones terminaron\"); });" },
  { lang: "JavaScript", question: "async function  ·  JavaScript · Promesas", answer: "Declara una función que siempre devuelve una promesa y permite usar await dentro. Ej: async function cargarDatos() {   const respuesta = await fetch(\"/api/usuarios\");   const datos = await respuesta.json();   return datos; }" },
  { lang: "JavaScript", question: "await  ·  JavaScript · Promesas", answer: "Pausa la ejecución de una función async hasta que la promesa se resuelva, sin bloquear la página. Ej: async function cargarDatos() {   const respuesta = await fetch(\"/api/usuarios\");   console.log(\"Ya llegó la respuesta\"); }" },
  { lang: "Python", question: "async def  ·  Python · Promesas", answer: "Declara una función asíncrona (una corrutina) que se puede pausar y reanudar. Ej: async def cargar_datos():     print(\"Cargando...\")     return \"datos\"" },
  { lang: "Python", question: "await  ·  Python · Promesas", answer: "Espera el resultado de una corrutina sin bloquear el resto del programa. Ej: async def main():     datos = await cargar_datos()     print(datos)" },
  { lang: "Python", question: "asyncio.run()  ·  Python · Promesas", answer: "Ejecuta una función async como punto de entrada del programa. Ej: import asyncio  async def main():     print(\"Hola async\")  asyncio.run(main())" },
  { lang: "Python", question: "asyncio.gather()  ·  Python · Promesas", answer: "Ejecuta varias corrutinas a la vez y espera a que todas terminen. Ej: import asyncio  async def main():     resultados = await asyncio.gather(tarea1(), tarea2())     print(resultados)" },
  { lang: "JavaScript", question: "fetch()  ·  JavaScript · Fetch", answer: "Envía una petición HTTP y devuelve una promesa con la respuesta. Ej: fetch(\"https://api.ejemplo.com/usuarios\")   .then(respuesta => respuesta.json())   .then(datos => console.log(datos));" },
  { lang: "JavaScript", question: "response.json()  ·  JavaScript · Fetch", answer: "Convierte el cuerpo de la respuesta en un objeto JavaScript, devolviendo otra promesa. Ej: const respuesta = await fetch(\"/api/usuarios\"); const datos = await respuesta.json(); console.log(datos);" },
  { lang: "JavaScript", question: "response.ok  ·  JavaScript · Fetch", answer: "Booleano que indica si la respuesta tuvo un código de estado 200-299. Ej: const respuesta = await fetch(\"/api/usuarios\"); if (!respuesta.ok) {   throw new Error(\"Algo salió mal: \" + respuesta.status); }" },
  { lang: "JavaScript", question: "fetch(url, { method })  ·  JavaScript · Fetch", answer: "El segundo argumento configura el método HTTP y el cuerpo de la petición. Ej: fetch(\"/api/usuarios\", {   method: \"POST\",   body: JSON.stringify({ nombre: \"Ana\" }), });" },
  { lang: "Python", question: "requests.get()  ·  Python · Fetch", answer: "Envía una petición HTTP GET y devuelve un objeto Response. Ej: import requests  respuesta = requests.get(\"https://api.ejemplo.com/usuarios\") print(respuesta.json())" },
  { lang: "Python", question: "response.json()  ·  Python · Fetch", answer: "Convierte el cuerpo de la respuesta en un diccionario o lista de Python. Ej: respuesta = requests.get(url) datos = respuesta.json() print(datos)" },
  { lang: "Python", question: "response.status_code  ·  Python · Fetch", answer: "Número que indica el resultado de la petición (200 éxito, 404 no encontrado...). Ej: respuesta = requests.get(url) if respuesta.status_code == 200:     print(\"Todo bien\")" },
  { lang: "Python", question: "requests.post()  ·  Python · Fetch", answer: "Envía una petición HTTP POST, normalmente con datos en el cuerpo. Ej: respuesta = requests.post(url, json={\"nombre\": \"Ana\"}) print(respuesta.status_code)" },
  { lang: "JavaScript", question: "Leer (GET)  ·  JavaScript · CRUD completo", answer: "fetch(url) sin opciones envía una petición GET y devuelve el recurso solicitado. Ej: async function leerTareas() {   const respuesta = await fetch(\"/api/tareas\");   return await respuesta.json(); }" },
  { lang: "JavaScript", question: "Crear (POST)  ·  JavaScript · CRUD completo", answer: "fetch(url, { method: 'POST', body }) crea un recurso nuevo con los datos enviados. Ej: async function crearTarea(texto) {   await fetch(\"/api/tareas\", {     method: \"POST\",     body: JSON.stringify({ texto }),   }); }" },
  { lang: "JavaScript", question: "Actualizar completo (PUT)  ·  JavaScript · CRUD completo", answer: "fetch(url, { method: 'PUT', body }) reemplaza todos los datos de un recurso existente. Ej: async function actualizarTarea(id, datos) {   await fetch(`/api/tareas/${id}`, {     method: \"PUT\",     body: JSON.stringify(datos),   }); }" },
  { lang: "JavaScript", question: "Actualizar parcial (PATCH)  ·  JavaScript · CRUD completo", answer: "fetch(url, { method: 'PATCH', body }) actualiza solo una parte del recurso. Ej: async function marcarCompletada(id) {   await fetch(`/api/tareas/${id}`, {     method: \"PATCH\",     body: JSON.stringify({ completada: true }),   }); }" },
  { lang: "JavaScript", question: "Eliminar (DELETE)  ·  JavaScript · CRUD completo", answer: "fetch(url, { method: 'DELETE' }) elimina el recurso indicado en la URL. Ej: async function eliminarTarea(id) {   await fetch(`/api/tareas/${id}`, { method: \"DELETE\" }); }" },
  { lang: "Python", question: "Leer (GET)  ·  Python · CRUD completo", answer: "requests.get(url) lee y devuelve el recurso solicitado. Ej: def leer_tareas():     respuesta = requests.get(url)     return respuesta.json()" },
  { lang: "Python", question: "Crear (POST)  ·  Python · CRUD completo", answer: "requests.post(url, json=datos) crea un recurso nuevo con los datos enviados. Ej: def crear_tarea(texto):     requests.post(url, json={\"texto\": texto})" },
  { lang: "Python", question: "Actualizar completo (PUT)  ·  Python · CRUD completo", answer: "requests.put(url, json=datos) reemplaza todos los datos de un recurso existente. Ej: def actualizar_tarea(id, datos):     requests.put(f\"{url}/{id}\", json=datos)" },
  { lang: "Python", question: "Actualizar parcial (PATCH)  ·  Python · CRUD completo", answer: "requests.patch(url, json=datos) actualiza solo una parte del recurso. Ej: def marcar_completada(id):     requests.patch(f\"{url}/{id}\", json={\"completada\": True})" },
  { lang: "Python", question: "Eliminar (DELETE)  ·  Python · CRUD completo", answer: "requests.delete(url) elimina el recurso indicado en la URL. Ej: def eliminar_tarea(id):     requests.delete(f\"{url}/{id}\")" },
  { lang: "JavaScript", question: "let  ·  JavaScript · Variables", answer: "Declara una variable con ámbito de bloque: solo existe dentro de las llaves {} donde se creó. Ej: let contador = 0; contador = contador + 1; console.log(contador); // → 1" },
  { lang: "JavaScript", question: "const  ·  JavaScript · Variables", answer: "Declara una variable que no se puede reasignar, aunque su contenido interno sí pueda cambiar. Ej: const lista = []; lista.push(1); console.log(lista); // → [1], la variable 'lista' nunca se reasignó" },
  { lang: "JavaScript", question: "var  ·  JavaScript · Variables", answer: "Declara una variable con ámbito de función (no de bloque) y sufre 'hoisting'. Ej: if (true) {   var y = 1; } console.log(y); // → 1, var 'se escapa' del bloque" },
  { lang: "JavaScript", question: "typeof  ·  JavaScript · Variables", answer: "Devuelve un string con el tipo de dato de un valor. Ej: const edad = 25; console.log(typeof edad); // → \"number\" console.log(typeof \"hola\"); // → \"string\"" },
  { lang: "JavaScript", question: "Hoisting  ·  JavaScript · Variables", answer: "Las declaraciones con var se mueven mentalmente al principio del ámbito, pero su asignación no. Ej: console.log(a); // → undefined, no da error var a = 5; console.log(a); // → 5" },
  { lang: "JavaScript", question: "Ámbito de bloque  ·  JavaScript · Variables", answer: "El código dentro de {} (un if, un for...) puede tener sus propias variables con let/const, invisibles fuera. Ej: for (let i = 0; i < 3; i++) {   console.log(i); } console.log(i); // → Error: i no existe aquí fuera" },
  { lang: "Python", question: "Asignación (=)  ·  Python · Variables", answer: "Python no distingue let/const: toda asignación crea o reemplaza una variable en su ámbito actual. Ej: x = 5 print(type(x))  # → <class 'int'> x = \"hola\" print(type(x))  # → <class 'str'>" },
  { lang: "Python", question: "global  ·  Python · Variables", answer: "Permite modificar dentro de una función una variable definida fuera de ella. Ej: contador = 0  def sumar():     global contador     contador += 1  sumar() print(contador)  # → 1" },
  { lang: "JavaScript", question: "for  ·  JavaScript · Bucles", answer: "Repite un bloque de código un número conocido de veces, controlado por un contador. Ej: for (let i = 0; i < 5; i++) {   console.log(i); } // imprime 0, 1, 2, 3, 4" },
  { lang: "JavaScript", question: "while  ·  JavaScript · Bucles", answer: "Repite un bloque mientras una condición sea verdadera, sin necesitar un contador. Ej: let i = 0; while (i < 5) {   console.log(i);   i++; }" },
  { lang: "JavaScript", question: "do...while  ·  JavaScript · Bucles", answer: "Igual que while, pero ejecuta el bloque al menos una vez antes de comprobar la condición. Ej: let i = 0; do {   console.log(i);   i++; } while (i < 5);" },
  { lang: "JavaScript", question: "for...of  ·  JavaScript · Bucles", answer: "Recorre los valores de un array (o cualquier iterable), uno a uno. Ej: const frutas = [\"manzana\", \"pera\"]; for (const fruta of frutas) {   console.log(fruta); }" },
  { lang: "JavaScript", question: "for...in  ·  JavaScript · Bucles", answer: "Recorre las claves (propiedades) de un objeto, no los valores de un array. Ej: const persona = { nombre: \"Ana\", edad: 30 }; for (const clave in persona) {   console.log(clave); // → \"nombre\", luego \"edad\" }" },
  { lang: "JavaScript", question: "break  ·  JavaScript · Bucles", answer: "Detiene por completo la ejecución del bucle, saliendo inmediatamente de él. Ej: for (let i = 0; i < 10; i++) {   if (i === 3) break;   console.log(i); } // imprime 0, 1, 2" },
  { lang: "JavaScript", question: "continue  ·  JavaScript · Bucles", answer: "Salta directamente a la siguiente vuelta del bucle, sin ejecutar el resto del código de esa iteración. Ej: for (let i = 0; i < 5; i++) {   if (i % 2 === 0) continue;   console.log(i); } // imprime 1, 3" },
  { lang: "Python", question: "for ... in range()  ·  Python · Bucles", answer: "Repite un bloque un número determinado de veces generando una secuencia de números. Ej: for i in range(5):     print(i) # imprime 0, 1, 2, 3, 4" },
  { lang: "Python", question: "while  ·  Python · Bucles", answer: "Repite un bloque mientras la condición indicada sea verdadera. Ej: i = 0 while i < 5:     print(i)     i += 1" },
  { lang: "Python", question: "for elemento in lista  ·  Python · Bucles", answer: "Recorre directamente los elementos de una lista, uno a uno, sin necesitar un índice. Ej: frutas = [\"manzana\", \"pera\"] for fruta in frutas:     print(fruta)" },
  { lang: "Python", question: "break / continue  ·  Python · Bucles", answer: "break detiene el bucle por completo; continue salta a la siguiente vuelta. Ej: for i in range(10):     if i == 3:         break     print(i) # imprime 0, 1, 2" },
  { lang: "JavaScript", question: "function saludar() {}  ·  JavaScript · Funciones", answer: "Declara una función con nombre, disponible en todo su ámbito incluso antes de la línea donde se escribe. Ej: function saludar(nombre) {   return \"Hola \" + nombre; } console.log(saludar(\"Ana\")); // → \"Hola Ana\"" },
  { lang: "JavaScript", question: "Function expression  ·  JavaScript · Funciones", answer: "Guarda una función (con o sin nombre) dentro de una variable; a diferencia de la declarada, no sufre hoisting. Ej: const saludar = function (nombre) {   return \"Hola \" + nombre; }; console.log(saludar(\"Ana\"));" },
  { lang: "JavaScript", question: "Arrow function  ·  JavaScript · Funciones", answer: "Sintaxis corta para funciones que no tiene su propio 'this': hereda el del contexto donde se define. Ej: const sumar = (a, b) => a + b; console.log(sumar(2, 3)); // → 5" },
  { lang: "JavaScript", question: "Parámetro por defecto  ·  JavaScript · Funciones", answer: "Asigna un valor a un parámetro cuando no se pasa nada al llamar la función. Ej: function saludar(nombre = \"invitado\") {   return \"Hola \" + nombre; } console.log(saludar()); // → \"Hola invitado\"" },
  { lang: "JavaScript", question: "Rest params (...args)  ·  JavaScript · Funciones", answer: "Agrupa un número indefinido de argumentos en un array dentro de la función. Ej: function sumarTodos(...numeros) {   return numeros.reduce((a, b) => a + b, 0); } console.log(sumarTodos(1, 2, 3)); // → 6" },
  { lang: "JavaScript", question: "return  ·  JavaScript · Funciones", answer: "Finaliza la función y entrega un valor a quien la llamó; sin return, devuelve undefined. Ej: function doble(x) {   return x * 2; } console.log(doble(5)); // → 10" },
  { lang: "JavaScript", question: "this en arrow vs función normal  ·  JavaScript · Funciones", answer: "En una función normal, 'this' depende de cómo se la llama; en una arrow function, 'this' es siempre el del contexto exterior. Ej: const obj = {   valor: 1,   normal() { return this.valor; }, }; console.log(obj.normal()); // → 1" },
  { lang: "Python", question: "def  ·  Python · Funciones", answer: "Declara una función en Python. Ej: def saludar(nombre):     return \"Hola \" + nombre  print(saludar(\"Ana\"))  # → \"Hola Ana\"" },
  { lang: "Python", question: "Parámetro por defecto  ·  Python · Funciones", answer: "Asigna un valor a un parámetro que se usa si no se pasa nada al llamar la función. Ej: def saludar(nombre=\"invitado\"):     return \"Hola \" + nombre  print(saludar())  # → \"Hola invitado\"" },
  { lang: "Python", question: "*args  ·  Python · Funciones", answer: "Agrupa argumentos posicionales indefinidos en una tupla dentro de la función. Ej: def sumar_todos(*numeros):     return sum(numeros)  print(sumar_todos(1, 2, 3))  # → 6" },
  { lang: "Python", question: "**kwargs  ·  Python · Funciones", answer: "Agrupa argumentos con nombre indefinidos en un diccionario dentro de la función. Ej: def config(**opciones):     print(opciones)  config(tema=\"oscuro\", idioma=\"es\")" },
  { lang: "JavaScript", question: "Object.keys()  ·  JavaScript · Arrays y objetos", answer: "Devuelve un array con los nombres de las propiedades (claves) de un objeto. Ej: const persona = { nombre: \"Ana\", edad: 30 }; console.log(Object.keys(persona)); // → [\"nombre\", \"edad\"]" },
  { lang: "JavaScript", question: "Object.values()  ·  JavaScript · Arrays y objetos", answer: "Devuelve un array con los valores de las propiedades de un objeto. Ej: const persona = { nombre: \"Ana\", edad: 30 }; console.log(Object.values(persona)); // → [\"Ana\", 30]" },
  { lang: "JavaScript", question: "Object.entries()  ·  JavaScript · Arrays y objetos", answer: "Devuelve un array de pares [clave, valor] a partir de un objeto. Ej: const persona = { nombre: \"Ana\", edad: 30 }; for (const [clave, valor] of Object.entries(persona)) {   console.log(clave, valor); }" },
  { lang: "JavaScript", question: "Desestructuración de arrays  ·  JavaScript · Arrays y objetos", answer: "Extrae valores de un array y los asigna a variables en una sola línea. Ej: const coordenadas = [10, 20]; const [x, y] = coordenadas; console.log(x, y); // → 10 20" },
  { lang: "JavaScript", question: "Desestructuración de objetos  ·  JavaScript · Arrays y objetos", answer: "Extrae propiedades de un objeto y las asigna a variables con el mismo nombre. Ej: const persona = { nombre: \"Ana\", edad: 30 }; const { nombre, edad } = persona; console.log(nombre, edad); // → Ana 30" },
  { lang: "JavaScript", question: "Spread (...)  ·  JavaScript · Arrays y objetos", answer: "Expande los elementos de un array u objeto dentro de otro array, objeto o llamada de función. Ej: const original = [1, 2, 3]; const copia = [...original, 4, 5]; console.log(copia); // → [1, 2, 3, 4, 5]" },
  { lang: "Python", question: ".keys()  ·  Python · Arrays y objetos", answer: "Devuelve las claves de un diccionario. Ej: persona = {\"nombre\": \"Ana\", \"edad\": 30} print(persona.keys())  # → dict_keys(['nombre', 'edad'])" },
  { lang: "Python", question: ".values()  ·  Python · Arrays y objetos", answer: "Devuelve los valores de un diccionario. Ej: persona = {\"nombre\": \"Ana\", \"edad\": 30} print(persona.values())  # → dict_values(['Ana', 30])" },
  { lang: "Python", question: ".items()  ·  Python · Arrays y objetos", answer: "Devuelve pares (clave, valor) de un diccionario. Ej: persona = {\"nombre\": \"Ana\", \"edad\": 30} for clave, valor in persona.items():     print(clave, valor)" },
  { lang: "JavaScript", question: "class  ·  JavaScript · Clases y constructores", answer: "Declara una plantilla para crear objetos con propiedades y métodos comunes. Ej: class Persona {   constructor(nombre) {     this.nombre = nombre;   } }" },
  { lang: "JavaScript", question: "constructor()  ·  JavaScript · Clases y constructores", answer: "Método especial que se ejecuta automáticamente al crear una instancia con 'new', para inicializar sus propiedades. Ej: class Persona {   constructor(nombre) {     this.nombre = nombre;   } } const ana = new Persona('Ana'); console.log(ana.nombre); // → 'Ana'" },
  { lang: "JavaScript", question: "this (en una clase)  ·  JavaScript · Clases y constructores", answer: "Hace referencia a la instancia concreta que se está creando o usando. Ej: class Persona {   constructor(nombre) {     this.nombre = nombre; // 'this' es la instancia que se está creando   } }" },
  { lang: "JavaScript", question: "new  ·  JavaScript · Clases y constructores", answer: "Crea una nueva instancia de una clase, ejecutando automáticamente su constructor. Ej: class Persona {   constructor(nombre) { this.nombre = nombre; } } const ana = new Persona('Ana'); console.log(ana instanceof Persona); // → true" },
  { lang: "JavaScript", question: "Método de instancia  ·  JavaScript · Clases y constructores", answer: "Función definida dentro de la clase que puede usar 'this' para acceder a los datos de esa instancia concreta. Ej: class Persona {   constructor(nombre) { this.nombre = nombre; }   saludar() {     return 'Hola, soy ' + this.nombre;   } } const ana = new Persona('Ana'); console.log(ana.saludar()); // → 'Hola, soy Ana'" },
  { lang: "JavaScript", question: "extends  ·  JavaScript · Clases y constructores", answer: "Permite que una clase herede propiedades y métodos de otra clase. Ej: class Persona {   constructor(nombre) { this.nombre = nombre; } } class Estudiante extends Persona {   // hereda 'nombre' y cualquier método de Persona }" },
  { lang: "JavaScript", question: "super()  ·  JavaScript · Clases y constructores", answer: "Llama al constructor de la clase padre; es obligatorio antes de usar 'this' en el constructor de una clase hija. Ej: class Persona {   constructor(nombre) { this.nombre = nombre; } } class Estudiante extends Persona {   constructor(nombre, curso) {     super(nombre);     this.curso = curso;   } }" },
  { lang: "JavaScript", question: "static  ·  JavaScript · Clases y constructores", answer: "Define un método o propiedad que pertenece a la clase en sí, no a sus instancias, y se llama sin crear un objeto. Ej: class Utilidades {   static sumar(a, b) {     return a + b;   } } console.log(Utilidades.sumar(2, 3)); // → 5, sin crear ninguna instancia" },
  { lang: "Python", question: "class  ·  Python · Clases y constructores", answer: "Declara una clase en Python. Ej: class Persona:     def __init__(self, nombre):         self.nombre = nombre" },
  { lang: "Python", question: "__init__  ·  Python · Clases y constructores", answer: "Método especial equivalente al constructor: se ejecuta al crear una instancia para inicializar sus atributos. Ej: class Persona:     def __init__(self, nombre):         self.nombre = nombre  ana = Persona(\"Ana\") print(ana.nombre)  # → \"Ana\"" },
  { lang: "Python", question: "self  ·  Python · Clases y constructores", answer: "Hace referencia a la instancia concreta dentro de los métodos de la clase (equivalente a 'this' en JavaScript). Ej: class Persona:     def __init__(self, nombre):         self.nombre = nombre      def saludar(self):         return \"Hola, soy \" + self.nombre" },
  { lang: "Python", question: "Herencia: class Hijo(Padre)  ·  Python · Clases y constructores", answer: "Permite que una clase herede atributos y métodos de otra clase. Ej: class Persona:     def __init__(self, nombre):         self.nombre = nombre  class Estudiante(Persona):     pass  # hereda todo de Persona" },
  { lang: "Python", question: "super()  ·  Python · Clases y constructores", answer: "Llama a un método de la clase padre desde la clase hija. Ej: class Persona:     def __init__(self, nombre):         self.nombre = nombre  class Estudiante(Persona):     def __init__(self, nombre, curso):         super().__init__(nombre)         self.curso = curso" },
  { lang: "JavaScript", question: "document.querySelectorAll()  ·  JavaScript · DOM", answer: "Devuelve una lista (NodeList) con TODOS los elementos que coinciden con un selector CSS. Ej: const items = document.querySelectorAll(\".item\"); items.forEach(item => {   item.style.color = \"blue\"; });" },
  { lang: "JavaScript", question: ".closest()  ·  JavaScript · DOM", answer: "Busca hacia arriba en el árbol del DOM el ancestro más cercano que coincide con un selector. Ej: lista.addEventListener(\"click\", (e) => {   const tarjeta = e.target.closest(\".tarjeta\");   console.log(tarjeta); });" },
  { lang: "JavaScript", question: ".matches()  ·  JavaScript · DOM", answer: "Comprueba si un elemento concreto coincide con un selector CSS, devolviendo true o false. Ej: document.addEventListener(\"click\", (e) => {   if (e.target.matches(\".boton-borrar\")) {     console.log(\"Se pulsó un botón de borrar\");   } });" },
  { lang: "JavaScript", question: "El objeto event  ·  JavaScript · Eventos", answer: "El callback de un evento recibe automáticamente un objeto con información sobre lo ocurrido. Ej: boton.addEventListener(\"click\", (event) => {   console.log(event.type); // → \"click\" });" },
  { lang: "JavaScript", question: "event.target  ·  JavaScript · Eventos", answer: "Referencia al elemento exacto sobre el que ocurrió el evento. Ej: lista.addEventListener(\"click\", (e) => {   console.log(e.target.textContent); });" },
  { lang: "JavaScript", question: "event.preventDefault()  ·  JavaScript · Eventos", answer: "Cancela el comportamiento por defecto del navegador para ese evento (por ejemplo, enviar un formulario). Ej: formulario.addEventListener(\"submit\", (e) => {   e.preventDefault(); // evita que la página se recargue   console.log(\"Formulario enviado sin recargar\"); });" },
  { lang: "JavaScript", question: "event.stopPropagation()  ·  JavaScript · Eventos", answer: "Evita que el evento siga propagándose (burbujeando) hacia los elementos padre. Ej: boton.addEventListener(\"click\", (e) => {   e.stopPropagation(); // el clic no llega al elemento padre });" },
  { lang: "JavaScript", question: "Burbujeo (bubbling)  ·  JavaScript · Eventos", answer: "Un evento disparado en un elemento hijo también se puede escuchar en sus elementos padre, porque 'sube' por el árbol del DOM. Ej: document.body.addEventListener(\"click\", () => {   console.log(\"Clic detectado en cualquier parte de la página\"); });" },
  { lang: "JavaScript", question: "Delegación de eventos  ·  JavaScript · Eventos", answer: "Escuchar el evento en un elemento padre en vez de en cada hijo, usando event.target para saber cuál se pulsó. Ej: lista.addEventListener(\"click\", (e) => {   if (e.target.tagName === \"LI\") {     e.target.classList.toggle(\"completada\");   } });" },
  { lang: "JavaScript", question: "window  ·  JavaScript · Objetos del navegador", answer: "Objeto global del navegador que representa la ventana; document, alert, setTimeout... son propiedades suyas. Ej: console.log(window.innerWidth); // ancho visible de la ventana window.scrollTo(0, 0);" },
  { lang: "JavaScript", question: "document  ·  JavaScript · Objetos del navegador", answer: "Representa la página cargada; es el punto de entrada para acceder y modificar el DOM. Ej: document.title = \"Nuevo título\"; console.log(document.body);" },
  { lang: "JavaScript", question: "location.href  ·  JavaScript · Objetos del navegador", answer: "Contiene (y permite cambiar) la URL actual de la página. Ej: console.log(location.href); // URL actual location.href = \"https://ejemplo.com\"; // navega a otra página" },
  { lang: "JavaScript", question: "setTimeout()  ·  JavaScript · Objetos del navegador", answer: "Ejecuta una función una sola vez, después de un tiempo determinado. Ej: console.log(\"Antes\"); setTimeout(() => {   console.log(\"Después de 1 segundo\"); }, 1000);" },
  { lang: "JavaScript", question: "alert() / confirm()  ·  JavaScript · Objetos del navegador", answer: "Muestran un cuadro de diálogo del navegador; confirm() además devuelve true o false según la elección del usuario. Ej: const quiereBorrar = confirm(\"¿Seguro que quieres borrar?\"); if (quiereBorrar) {   console.log(\"Elemento borrado\"); }" },
  { lang: "JavaScript", question: "export  ·  JavaScript · Módulos ES6", answer: "Hace que una variable, función o clase de un archivo esté disponible para importarla en otro. Ej: // operaciones.js export function sumar(a, b) {   return a + b; }" },
  { lang: "JavaScript", question: "export default  ·  JavaScript · Módulos ES6", answer: "Exporta un único valor principal por archivo, que se puede importar con cualquier nombre. Ej: // App.js export default function App() {   console.log(\"Aplicación iniciada\"); }" },
  { lang: "JavaScript", question: "import { }  ·  JavaScript · Módulos ES6", answer: "Trae una exportación concreta (con nombre) de otro archivo para poder usarla. Ej: import { sumar } from \"./operaciones.js\"; console.log(sumar(2, 3)); // → 5" },
  { lang: "JavaScript", question: "import ... as  ·  JavaScript · Módulos ES6", answer: "Permite importar algo con un nombre distinto al que tiene en el archivo original. Ej: import { sumar as add } from \"./operaciones.js\"; console.log(add(2, 3)); // → 5" },
  { lang: "JavaScript", question: "import * as  ·  JavaScript · Módulos ES6", answer: "Importa todas las exportaciones de un archivo agrupadas en un solo objeto. Ej: import * as operaciones from \"./operaciones.js\"; console.log(operaciones.sumar(2, 3));" },
  { lang: "JavaScript", question: "( )  ·  la pregunta mental  ·  JavaScript · Símbolos", answer: "¿Voy a ejecutar algo? Los paréntesis ejecutan, declaran lo que recibe una función o agrupan una operación. Ej: saludar();                    // ejecutar function saludar(nombre) { }  // lo que recibe (2 + 3) * 4                   // agrupar" },
  { lang: "JavaScript", question: "[ ]  ·  la pregunta mental  ·  JavaScript · Símbolos", answer: "¿Voy a acceder o guardar elementos? Los corchetes crean listas o acceden a una posición. Ej: const frutas = [\"manzana\", \"pera\"];  // guardar frutas[0];                            // acceder" },
  { lang: "JavaScript", question: "{ }  ·  la pregunta mental  ·  JavaScript · Símbolos", answer: "¿Voy a agrupar o definir cosas? Las llaves delimitan un bloque o definen un objeto. Ej: if (activo) { encender(); }              // bloque const p = { nombre: \"Ana\", edad: 30 };   // objeto" },
  { lang: "JavaScript", question: "{ }: ¿bloque u objeto?  ·  JavaScript · Símbolos", answer: "Tras un = o dentro de un ( ) es un objeto; tras if, for, function o => es un bloque de código. Ej: const persona = { nombre: \"Ana\" }; // objeto: va tras un =  if (activo) {                      // bloque: va tras un if   encender(); }" },
  { lang: "JavaScript", question: "fn  vs  fn()  ·  JavaScript · Símbolos", answer: "Sin paréntesis pasas la función para que se ejecute después; con paréntesis la ejecutas ya y usas su resultado. Ej: boton.addEventListener('click', saludar);   // correcto: se llamara al hacer clic boton.addEventListener('click', saludar()); // error clasico: se ejecuta ya" },
  { lang: "JavaScript", question: "obj[clave]  vs  obj.clave  ·  JavaScript · Símbolos", answer: "Los corchetes evalúan lo de dentro (una variable); el punto toma el nombre literal. Ej: const campo = \"edad\";  persona[campo];  // usa el VALOR de campo, es decir persona.edad persona.campo;   // busca una propiedad llamada literalmente \"campo\"" },
  { lang: "JavaScript", question: "Desestructurar: [ ] o { }  ·  JavaScript · Símbolos", answer: "Corchetes si lo que repartes es un array (por posición); llaves si es un objeto (por nombre). Ej: const [x, y] = coordenadas;      // array: importa el ORDEN const { nombre, edad } = persona; // objeto: importa el NOMBRE" },
  { lang: "JavaScript", question: "${ } (interpolación)  ·  JavaScript · Símbolos", answer: "Mete el valor de una variable dentro de un texto, y solo funciona con comillas invertidas ` `. Ej: const nombre = \"Ana\";  `Hola ${nombre}`;  // \"Hola Ana\" \"Hola ${nombre}\";  // \"Hola ${nombre}\" tal cual" },
  { lang: "JavaScript", question: "=>  (arrow function)  ·  JavaScript · Símbolos", answer: "Declara una función en forma corta; si no lleva llaves, devuelve el resultado directamente. Ej: const doble = (n) => n * 2;        // devuelve n * 2 const log = (n) => { console.log(n); }; // con llaves: bloque, no devuelve" },
  { lang: "JavaScript", question: "...  (spread y rest)  ·  JavaScript · Símbolos", answer: "Expande los elementos de una lista, o recoge los que sobran en una nueva. Ej: const copia = [...original, 4];        // expande function sumar(...numeros) { }         // recoge todos los argumentos" },
  { lang: "JavaScript", question: "?.  (encadenamiento opcional)  ·  JavaScript · Símbolos", answer: "Accede a la propiedad solo si el valor existe; si no, devuelve undefined en vez de romperse. Ej: usuario.direccion.calle;    // revienta si direccion no existe usuario?.direccion?.calle;  // devuelve undefined sin romperse" },
  { lang: "JavaScript", question: ":  vs  =  ·  JavaScript · Símbolos", answer: "Los dos puntos asignan dentro de un objeto; el igual asigna a una variable. Ej: let nombre = \"Ana\";                // variable: igual const p = { nombre: \"Ana\" };       // dentro del objeto: dos puntos" },
  { lang: "JavaScript", question: "Comillas invertidas ` `  ·  JavaScript · Símbolos", answer: "Permiten meter variables con ${ } y escribir varias líneas sin concatenar. Ej: const mensaje = `Hola ${nombre}, tienes ${edad} anios`; // admite variables y saltos de linea" },
  { lang: "JavaScript", question: "( ) para agrupar  ·  JavaScript · Símbolos", answer: "Cambian el orden en que se resuelve una operación, igual que en matemáticas. Ej: 2 + 3 * 4;    // 14: primero multiplica (2 + 3) * 4;  // 20: primero el parentesis" },
  { lang: "TypeScript", question: "Anotación de tipo  ·  TypeScript", answer: "Indica explícitamente qué tipo de dato puede tener una variable o parámetro. Ej: let edad: number = 25; let nombre: string = \"Ana\"; let activo: boolean = true;  edad = \"treinta\"; // Error: Type 'string' is not assignable to type 'number'" },
  { lang: "TypeScript", question: "Inferencia de tipos  ·  TypeScript", answer: "TypeScript deduce el tipo del valor asignado, así que no hace falta anotarlo todo. Ej: let nombre: string = \"Ana\"; // redundante let nombre = \"Ana\";         // ya sabe que es string  const precios = [10, 20];   // inferido: number[]" },
  { lang: "TypeScript", question: "Tipar parámetros  ·  TypeScript", answer: "Los parámetros de una función sí hay que anotarlos: es lo que TS no puede adivinar. Ej: function saludar(nombre: string) {   return \"Hola \" + nombre; // retorno inferido: string }" },
  { lang: "TypeScript", question: "Tipo de retorno / void  ·  TypeScript", answer: "Se anota tras los paréntesis; void significa que la función no devuelve nada. Ej: function registrar(mensaje: string): void {   console.log(mensaje); }  function sumar(a: number, b: number): number {   return a + b; }" },
  { lang: "TypeScript", question: "interface  ·  TypeScript", answer: "Define la forma (propiedades y tipos) que debe tener un objeto. Ej: interface Persona {   nombre: string;   edad: number; }  const ana: Persona = { nombre: \"Ana\", edad: 30 };" },
  { lang: "TypeScript", question: "Propiedad opcional (?)  ·  TypeScript", answer: "Marca una propiedad o parámetro como opcional: puede no estar presente. Ej: interface Persona {   nombre: string;   apodo?: string; }  const ana: Persona = { nombre: \"Ana\" }; // valido sin apodo" },
  { lang: "TypeScript", question: "Arrays tipados (T[])  ·  TypeScript", answer: "Declara una lista en la que todos los elementos son del mismo tipo. Ej: const precios: number[] = [10, 20]; const nombres: string[] = [\"Ana\", \"Luis\"]; const usuarios: Persona[] = [{ nombre: \"Ana\", edad: 30 }];" },
  { lang: "TypeScript", question: "Uniones (string | number)  ·  TypeScript", answer: "Permite que un valor sea de varios tipos posibles. Ej: type Id = string | number;  let id: Id = \"abc123\"; id = 42;    // tambien vale id = true;  // Error: no esta en la union" },
  { lang: "TypeScript", question: "Narrowing con typeof  ·  TypeScript", answer: "Al comprobar el tipo, TS descarta opciones y te deja usar solo lo válido en cada rama. Ej: function formatear(id: string | number) {   if (typeof id === \"string\") {     return id.toUpperCase(); // aqui TS sabe que es string   }   return id.toFixed(2);      // aqui solo puede ser number }" },
  { lang: "TypeScript", question: "Tipos literales  ·  TypeScript", answer: "Limita el valor a una lista exacta de opciones concretas. Ej: type Estado = \"pendiente\" | \"enviado\" | \"entregado\";  let estado: Estado = \"enviado\";  // valido estado = \"enviadoo\";             // Error: el typo se detecta al escribirlo" },
  { lang: "TypeScript", question: "type (alias)  ·  TypeScript", answer: "Crea un alias con nombre propio para un tipo, útil para uniones o tipos reutilizados. Ej: type Id = string | number; type Callback = (n: number) => void; type Punto = { x: number; y: number };" },
  { lang: "TypeScript", question: "any  ·  TypeScript", answer: "Tipo comodín que desactiva la comprobación de tipos; conviene evitarlo. Ej: let dato: any = \"texto\"; dato = 42; dato.metodoQueNoExiste(); // compila, pero revienta al ejecutarse" },
  { lang: "TypeScript", question: "unknown  ·  TypeScript", answer: "Como any pero seguro: obliga a comprobar el tipo antes de usar el valor. Ej: let dato: unknown = await res.json();  dato.toUpperCase();                       // Error: hay que comprobar antes if (typeof dato === \"string\") dato.toUpperCase(); // correcto" },
  { lang: "TypeScript", question: "Genéricos <T>  ·  TypeScript", answer: "Un hueco que se rellena en cada llamada, conservando el tipo que entra. Ej: function primero<T>(lista: T[]): T {   return lista[0]; }  const n = primero([1, 2, 3]);   // n es number const s = primero([\"a\", \"b\"]); // s es string" },
  { lang: "TypeScript", question: "Tipar el DOM  ·  TypeScript", answer: "Se concreta qué elemento esperas, y hay que contemplar que el selector devuelva null. Ej: const input = document.querySelector<HTMLInputElement>(\"#email\");  if (input) {   console.log(input.value); // comprobado el null }" },
  { lang: "TypeScript", question: "Promise<T> y async  ·  TypeScript", answer: "El tipo dentro de Promise es lo que se obtiene al hacer await. Ej: async function cargarUsuarios(): Promise<Persona[]> {   const res = await fetch(\"/api/usuarios\");   return res.json(); }  const usuarios = await cargarUsuarios(); // Persona[]" },
  { lang: "TypeScript", question: "Tipar callbacks  ·  TypeScript", answer: "Se describe qué recibe y qué devuelve la función que se pasa como parámetro. Ej: function repetir(veces: number, accion: (i: number) => void) {   for (let i = 0; i < veces; i++) accion(i); }  repetir(3, (i) => console.log(i)); // i es number, sin anotarlo" },
  { lang: "TypeScript", question: "readonly  ·  TypeScript", answer: "Impide reasignar esa propiedad después de crear el objeto. Ej: interface Config {   readonly apiUrl: string; }  config.apiUrl = \"otra\"; // Error: Cannot assign to 'apiUrl'" },
  { lang: "TypeScript", question: "Partial<T>  ·  TypeScript", answer: "Crea una versión del tipo con todas sus propiedades opcionales. Ej: interface Usuario { id: number; nombre: string }  function actualizar(id: number, cambios: Partial<Usuario>) { } actualizar(1, { nombre: \"Ana\" }); // no hace falta pasar todo" },
  { lang: "TypeScript", question: "Pick y Omit  ·  TypeScript", answer: "Derivan un tipo nuevo eligiendo o descartando propiedades de otro. Ej: type SoloNombre = Pick<Usuario, \"nombre\">;  // solo esa propiedad type SinId = Omit<Usuario, \"id\">;           // todas menos esa" },
  { lang: "TypeScript", question: "Record<K, V>  ·  TypeScript", answer: "Describe un objeto usado como diccionario: claves de un tipo, valores de otro. Ej: const porId: Record<number, Usuario> = {   1: { id: 1, nombre: \"Ana\" }, };" },
  { lang: "TypeScript", question: "extends (interfaces)  ·  TypeScript", answer: "Una interface hereda las propiedades de otra y añade las suyas. Ej: interface Persona { nombre: string } interface Empleado extends Persona {   puesto: string; } // Empleado tiene nombre Y puesto" },
  { lang: "TypeScript", question: "as const  ·  TypeScript", answer: "Congela los valores como literales de solo lectura, útil para derivar tipos de un array real. Ej: const ESTADOS = [\"pendiente\", \"enviado\"] as const; type Estado = (typeof ESTADOS)[number]; // resultado: \"pendiente\" | \"enviado\", derivado de la lista real" },
  { lang: "TypeScript", question: "Aserción (as)  ·  TypeScript", answer: "Le dices a TS que confíe en ti sobre el tipo; si te equivocas, no hay red. Ej: const input = document.getElementById(\"email\") as HTMLInputElement;  // Ojo: no convierte nada, solo silencia la comprobacion" },
  { lang: "TypeScript", question: "Encadenamiento opcional (?.)  ·  TypeScript", answer: "Accede a la propiedad solo si el valor existe, evitando el error de null/undefined. Ej: const usuario = usuarios.find(u => u.id === 1);  console.log(usuario.nombre);  // Error: possibly undefined console.log(usuario?.nombre); // correcto" },
  { lang: "TypeScript", question: "Tuplas  ·  TypeScript", answer: "Un array de longitud fija donde cada posición tiene su propio tipo. Ej: const punto: [number, number] = [40.4, -3.7]; const par: [string, boolean] = [\"activo\", true];" },
  { lang: "TypeScript", question: "strict en tsconfig  ·  TypeScript", answer: "Activa las comprobaciones estrictas: sin él TypeScript apenas protege. Ej: // tsconfig.json {   \"compilerOptions\": {     \"strict\": true   } }" },
];

